import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    for (int i = 1; i <= n; i++) {
        boolean first = true;
        for (int j = 1; j <= n; j++) {
            int r = sc.nextInt();
            if (r == 1) {
                if (!first) {
                    System.out.print(" ");
                }
                System.out.print(j);
                first = false;
            }
        }
        System.out.println();
    }
    sc.close();
}
